// v3.316.19: in-memory audit log for write operations (ring buffer, last 1000 entries)
const PCC_AUDIT_MAX = 1000;
const pccAuditLog = [];
function pccAuditEntry(entry) {
  const e = {
    ts: new Date().toISOString(),
    method: entry.method,
    path: entry.path,
    tenant_id: entry.tenant_id || null,
    decision_id: entry.decision_id || null,
    fn: entry.fn || null,
    module: entry.module || null,
    duration_ms: entry.duration_ms || null,
    status: entry.status || null
  };
  pccAuditLog.push(e);
  if (pccAuditLog.length > PCC_AUDIT_MAX) pccAuditLog.shift();
}

const PORT = parseInt(process.env.PCC_PORT || '3100', 10);
const app = express();

// --- Security middleware ---
// v3.316.17: CSP allows cdn.tailwindcss.com + fonts.googleapis.com + fonts.gstatic.com
// (only consumed by the Admin Dashboard at /admin). Tightened defaults kept everywhere else.
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "https://cdn.tailwindcss.com"],
      styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
      fontSrc: ["'self'", "https://fonts.gstatic.com"],
      imgSrc: ["'self'", "data:"],
      objectSrc: ["'none'"],
      frameAncestors: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: false,
}));
app.use(cors({
  origin: process.env.PCC_CORS_ORIGIN || 'http://localhost:3100',
  credentials: true,
  // v3.316.22: expose rate-limit + audit headers to browser/SDK clients.
  // Without this, browsers strip X-RateLimit-* and X-Audit-Request-Id
  // from cross-origin responses, so SDKs can't display user rate-limit budgets.
  exposedHeaders: [
    'X-RateLimit-Limit',
    'X-RateLimit-Remaining',
    'X-RateLimit-Reset',
    'X-RateLimit-Limit-Tenant',
    'X-RateLimit-Remaining-Tenant',
    'X-RateLimit-Reset-Tenant',
    'X-Audit-Request-Id',
  ],
}));
app.use(express.json({ limit: '256kb' }));
app.use(morgan('tiny'));

// --- v3.316.11: per-IP rate limit for write endpoints (record / call) ---
// In-memory token bucket, sliding 60s window, max 60 req/min per IP.
// No external deps. Only gates POST/PUT to /api/v1/<slug>/record and /api/v1/<slug>/call/*.
// GET endpoints (list, read-only helpers) and /health pass through untouched.
const PCC_RL_WINDOW_MS = 60_000;
const PCC_RL_MAX = 60;
const pccRateBuckets = new Map();
// Periodic GC so the Map doesn't grow unbounded across long uptimes.
setInterval(() => {
  const now = Date.now();
  for (const [ip, b] of pccRateBuckets) {
    if (now - b.start > PCC_RL_WINDOW_MS * 2) pccRateBuckets.delete(ip);
  }
}, PCC_RL_WINDOW_MS).unref();

function pccRateLimit(req, res, next) {
  // Only gate writes.
  if (req.method !== 'POST' && req.method !== 'PUT') return next();
  // Only gate /api/v1/* paths.
  const url = req.originalUrl || req.url || '';
  if (!url.startsWith('/api/v1/')) return next();
  // Only gate /record and /call/* sub-paths. /list and friends pass through.
  const pathOnly = url.split('?')[0];
  const isWrite = /\/record(?:\/|$)/.test(pathOnly) || /\/call\//.test(pathOnly) || pathOnly.endsWith('/record');
  if (!isWrite) return next();

  const ip = (req.headers['x-forwarded-for'] || '').toString().split(',')[0].trim()
    || req.ip
    || (req.connection && req.connection.remoteAddress)
    || 'unknown';
  const now = Date.now();
  let bucket = pccRateBuckets.get(ip);
  if (!bucket || now - bucket.start > PCC_RL_WINDOW_MS) {
    bucket = { start: now, count: 0 };
    pccRateBuckets.set(ip, bucket);
  }
  bucket.count += 1;
  const remaining = Math.max(0, PCC_RL_MAX - bucket.count);
  res.set('X-RateLimit-Limit', String(PCC_RL_MAX));
  res.set('X-RateLimit-Remaining', String(remaining));
  if (bucket.count > PCC_RL_MAX) {
    const retryAfter = Math.max(1, Math.ceil((PCC_RL_WINDOW_MS - (now - bucket.start)) / 1000));
    res.set('Retry-After', String(retryAfter));
    // v3.316.22: persist 429 to PG (env-gated, no-op unless PCC_AUDIT_PERSIST=true)
    if (process.env.PCC_AUDIT_PERSIST === 'true') {
      recordRateLimitEvent(POOL, {
        ip: req.ip || (req.connection && req.connection.remoteAddress) || 'unknown',
        endpoint: req.originalUrl || req.url || '',
        count: PCC_RL_MAX - remaining,
      });
    }
    return res.status(429).json({
      error: 'rate limit exceeded',
      retry_after_seconds: retryAfter,
      limit: PCC_RL_MAX,
      window_seconds: Math.floor(PCC_RL_WINDOW_MS / 1000),
    });
  }
  return next();
}

// v3.316.21: write-audit middleware — registered BEFORE pccRateLimit so 429s
// from pccRateLimit (and pccTenantRateLimit) are still captured. Same shape as
// the v3.316.19 listener; the old post-rate-limit registration has been removed
// to avoid double-auditing.
app.use((req, res, next) => {
  if (req.method !== 'POST') return next();
  const fullPath = req.path || req.url || '';
  if (!/\/api\/v1\//.test(fullPath)) return next();
  const isWrite = /\/record$/.test(fullPath) || /\/call\//.test(fullPath);
  if (!isWrite) return next();
  const start = Date.now();
  res.on('finish', () => {
    const auditFields = {
      method: req.method,
      path: fullPath,
      tenant_id: (req.body && req.body.tenant_id) || null,
      decision_id: (req.body && req.body.decisionId) || null,
      fn: (req.body && req.body.fn) || null,
      module: fullPath.split('/').slice(0, 4).join('/'),
      duration_ms: Date.now() - start,
      status: res.statusCode
    };
    // v3.316.19: in-memory ring buffer (always on)
    pccAuditEntry(auditFields);
    // v3.316.21: optional PG persistence (no-op when PCC_AUDIT_PERSIST !== 'true')
    if (process.env.PCC_AUDIT_PERSIST === 'true') {
      recordAuditEntry(POOL, {
        ts: new Date().toISOString(),
        method: auditFields.method,
        path: auditFields.path,
        status: auditFields.status,
        ip: (req.headers['x-forwarded-for'] || '').toString().split(',')[0].trim()
            || req.ip
            || (req.connection && req.connection.remoteAddress)
            || null,
        tenant_id: auditFields.tenant_id,
        decision_id: auditFields.decision_id,
        user_agent: req.headers['user-agent'] || null,
        duration_ms: auditFields.duration_ms
      });
    }
  });
  return next();
});

// v3.316.21: HTTP counter + v3.316.22 latency histogram — registered very early
// so every response (including 429s, 401s, 404s) is observed. Cheap.
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    try {
      const duration = (Date.now() - start) / 1000;
      incrementHttp(req.method, res.statusCode);
      // Route template: prefer req.route?.path (e.g. "/:id") plus baseUrl,
      // fall back to req.path without query string.
      const route = (req.route && req.route.path)
        ? (req.baseUrl || '') + req.route.path
        : (req.path || '').split('?')[0];
      observeLatency(req.method, route, duration);
    } catch (_) { /* never throw on metrics */ }
  });
  return next();
});

// v3.316.11: MUST be registered BEFORE the 1322 router mounts so the gate
// runs on every write that reaches a router.
app.use(pccRateLimit);

// v3.316.25: warm-cache of valid tokens, refreshed from PG every 60s.
// The cache is what pccBearerAuth checks synchronously; PG is the source
// of truth (see token_store.js). On startup the cache is empty; tokens
// become validatable within 60s of issue, or immediately on issue (the
// POST /api-token handler primes the cache).
const pccIssuedTokens = new Map(); // token -> { label, expires_at (ms) }
let pccTokenCacheLastSync = 0;
async function pccSyncTokenCache() {
  if (!POOL) return;
  const now = Date.now();
  if (now - pccTokenCacheLastSync < 60 * 1000) return;
  pccTokenCacheLastSync = now;
  try {
    const r = await POOL.query(
      `SELECT token, label, expires_at FROM ${'pcc_api_tokens'} WHERE revoked_at IS NULL AND expires_at > NOW()`
    );
    pccIssuedTokens.clear();
    for (const row of r.rows) {
      pccIssuedTokens.set(row.token, {
        label: row.label,
        expires_at: new Date(row.expires_at).getTime(),
      });
    }
  } catch (e) {
    console.error('[token_cache] sync failed:', e.message);
  }
}
// Trigger initial sync (fire-and-forget; auth stays permissive until populated)
pccSyncTokenCache();
const PCC_TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

function pccGenerateToken() {
  return require('crypto').randomBytes(32).toString('hex');
}

// v3.316.17: Bearer-token auth for write endpoints (opt-in via env var)
// Disabled when PCC_API_TOKEN is unset (backward compat for sandbox).
// Protects POST/PUT/DELETE under /api/v1/ except for read-only paths.
const PCC_API_TOKEN = process.env.PCC_API_TOKEN || null;
function pccBearerAuth(req, res, next) {
  // v3.316.24: If no env-var token AND no issued tokens, middleware is
  // disabled (backward compat for sandbox default).
  // v3.316.25: also try to lazy-populate the warm cache from PG before
  // giving up — tokens survive restarts in the DB, so an empty cache
  // may simply mean we haven't synced yet.
  if (!PCC_API_TOKEN && pccIssuedTokens.size === 0) {
    if (POOL) pccSyncTokenCache();
    return next();
  }
  // Only protect write endpoints.
  if (req.method !== 'POST' && req.method !== 'PUT' && req.method !== 'DELETE') return next();
  const path = req.path || req.url || '';
  // Only protect /api/v1/* traffic.
  if (!/\/api\/v1\//.test(path)) return next();
  // Allow read-only / utility endpoints even on POST probes.
  // v3.316.24: /api-token is exempt so clients can bootstrap a token without
  // already having one (chicken-and-egg). GET /api-token only returns metadata.
  // v3.316.25: /api-token/revoke is also exempt so clients can revoke even
  // if their only valid token is the one being revoked.
  if (/\/(health|docs|openapi-pcc\.yaml|ping|coverage|stats|random|duplicates|orphans|search|lookup|function\/|module\/|categories|modules|api-token(?:\/revoke)?)$/.test(path)) return next();

  const auth = req.headers['authorization'] || '';
  const token = String(auth).replace(/^Bearer\s+/i, '').trim();
  if (!token) {
    return res.status(401).json({
      error: 'unauthorized',
      hint: 'Set Authorization: Bearer <token> header. Configure PCC_API_TOKEN env var or POST /api/v1/pcc-catalog/api-token to issue one.'
    });
  }
  // v3.316.17: env-var configured token
  if (PCC_API_TOKEN && token === PCC_API_TOKEN) return next();
  // v3.316.24: in-memory issued token (with expiry + lazy cleanup)
  if (pccIssuedTokens.size > 0 && pccIssuedTokens.has(token)) {
    const meta = pccIssuedTokens.get(token);
    if (meta.expires_at > Date.now()) return next();
    pccIssuedTokens.delete(token); // expired, remove
  }
  return res.status(401).json({
    error: 'unauthorized',
    hint: 'Set Authorization: Bearer <token> header. Configure PCC_API_TOKEN env var or POST /api/v1/pcc-catalog/api-token to issue one.'
  });
}
app.use(pccBearerAuth);

// v3.316.19: per-tenant rate limit (in addition to per-IP). Only protects
// POST /api/v1/<slug>/record. Skips when tenant_id is missing (record
// handler will already 400). 100 req/min per tenant_id.
const pccTenantBuckets = new Map();
const PCC_TENANT_RL_WINDOW_MS = 60000;
const PCC_TENANT_RL_MAX = 100;
function pccTenantRateLimit(req, res, next) {
  if (req.method !== 'POST') return next();
  if (!req.path || !/\/record$/.test(req.path)) return next();
  const tenantId = (req.body && req.body.tenant_id) || null;
  if (!tenantId) return next(); // record handler will 400 if missing

  const now = Date.now();
  let bucket = pccTenantBuckets.get(tenantId);
  if (!bucket || now - bucket.start > PCC_TENANT_RL_WINDOW_MS) {
    bucket = { start: now, count: 0 };
    pccTenantBuckets.set(tenantId, bucket);
  }// v3.316.22: persist 429 to PG (env-gated, no-op unless PCC_AUDIT_PERSIST=true).
    // Tenant-based 429s are tagged with 'tenant:<id>' as the ip field so they
    // can be distinguished from per-IP 429s in pcc_rate_limit_log.
    if (process.env.PCC_AUDIT_PERSIST === 'true') {
      recordRateLimitEvent(POOL, {
        ip: 'tenant:' + tenantId,
        endpoint: req.originalUrl || req.url || '',
        count: PCC_TENANT_RL_MAX - remaining,
      });
    }
    
  bucket.count += 1;
  const remaining = Math.max(0, PCC_TENANT_RL_MAX - bucket.count);
  res.set('X-RateLimit-Limit-Tenant', String(PCC_TENANT_RL_MAX));
  res.set('X-RateLimit-Remaining-Tenant', String(remaining));
  if (bucket.count > PCC_TENANT_RL_MAX) {
    const retryAfter = Math.max(1, Math.ceil((PCC_TENANT_RL_WINDOW_MS - (now - bucket.start)) / 1000));
    res.set('Retry-After', String(retryAfter));
    return res.status(429).json({
      error: 'tenant rate limit exceeded',
      tenant_id: tenantId,
      retry_after_seconds: retryAfter,
      limit_per_minute: PCC_TENANT_RL_MAX,
      window_seconds: Math.floor(PCC_TENANT_RL_WINDOW_MS / 1000),
    });
  }
  return next();
}
app.use(pccTenantRateLimit);
// Periodic GC to prevent memory leak from one-shot tenants
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of pccTenantBuckets.entries()) {
    if (now - v.start > PCC_TENANT_RL_WINDOW_MS) pccTenantBuckets.delete(k);
  }
}, PCC_TENANT_RL_WINDOW_MS).unref();

