// --- v3.316.21: K8s-style health probes (lightweight, no DB, no auth) ---
// /healthz   - liveness-only ping (200 if process responds). Plain text.
// /livez     - alias of /healthz with distinct body for tooling.
// /readyz    - readiness gate: uptime>0 AND RSS<4GB. JSON w/ sub-checks.
const pccProbeStart = Date.now();
app.get('/healthz', (_req, res) => res.status(200).type('text/plain').send('ok'));
app.get('/livez',  (_req, res) => res.status(200).type('text/plain').send('alive'));
app.get('/readyz', (_req, res) => {
  const checks = {
    uptime_seconds: Math.floor((Date.now() - pccProbeStart) / 1000),
    memory_mb: Math.round(process.memoryUsage().rss / 1024 / 1024),
    audit_log_size: (typeof pccAuditLog !== 'undefined' && Array.isArray(pccAuditLog)) ? pccAuditLog.length : 0,
    event_loop_lag_ms: 0, // would need native binding; report 0 (healthy) by default
    build: HEALTH_BUILD_VERSION,
  };
  const ready = checks.uptime_seconds > 0 && checks.memory_mb < 4096;
  res.status(ready ? 200 : 503).json({ status: ready ? 'ready' : 'not_ready', checks });
});

// --- v3.316.28: SSE replay buffer — last 30 events for reconnecting clients ---
// Reconnecting clients first receive the buffered events (catch-up), then
// continue with the live stream so they don't miss recent updates.
const pccSSEBuffer = [];
const PCC_SSE_BUFFER_MAX = 30;

function pccSSEPushEvent(event) {
  pccSSEBuffer.push(event);
  if (pccSSEBuffer.length > PCC_SSE_BUFFER_MAX) pccSSEBuffer.shift();
}

function pccSSEBuildPayload() {
  const uptime = process.uptime();
  const mem = process.memoryUsage();
  return {
    event: 'status',
    captured_at: new Date().toISOString(),
    uptime_seconds: Math.floor(uptime),
    memory_mb: Math.round(mem.rss / 1024 / 1024),
    build: HEALTH_BUILD_VERSION,
  };
}

// --- v3.316.27: Server-Sent Events for live status updates (v3.316.28: +replay buffer) ---
// Streams a status JSON event every 5 seconds plus a 15-second comment heartbeat
// to defeat proxy idle timeouts. Cleans up intervals on client disconnect.
app.get('/status/stream', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    'Connection': 'keep-alive',
    'Access-Control-Allow-Origin': '*',
    'X-Accel-Buffering': 'no', // disable nginx buffering
  });

  // v3.316.28: Replay buffered events on connect (catch-up for reconnects)
  for (const evt of pccSSEBuffer) {
    res.write('event: ' + evt.event + '\n');
    res.write('data: ' + JSON.stringify(evt) + '\n\n');
  }

  const sendStatus = () => {
    const payload = pccSSEBuildPayload();
    pccSSEPushEvent(payload); // record for future reconnects
    res.write('event: ' + payload.event + '\n');
    res.write('data: ' + JSON.stringify(payload) + '\n\n');
  };

  // Send a fresh event immediately to confirm the live stream
  sendStatus();

  // Send every 5 seconds
  const interval = setInterval(sendStatus, 5000);

  // Heartbeat comment every 15 seconds (prevents proxy timeouts)
  const heartbeat = setInterval(() => {
    res.write(':heartbeat\n\n');
  }, 15000);

  // Cleanup on client disconnect
  req.on('close', () => {
    clearInterval(interval);
    clearInterval(heartbeat);
  });
});

