// v3.316.20: GraphQL execution endpoint
// Minimal executor at ./graphql/executor.js (no new npm deps).
// POST a { query, variables, operationName } JSON body; the executor fans out
// to internal PCC REST endpoints (modules/stats/coverage/audit/call/record)
// and projects the result according to the inline selection set.
const { executeQuery: pccExecuteGraphQL } = require('./graphql/executor');
app.post('/graphql/query', async (req, res) => {
  try {
    const result = await pccExecuteGraphQL(req.body || {});
    res.json(result);
  } catch (e) {
    res.status(400).json({ errors: [{ message: String(e && e.message || e) }] });
  }
});
app.get('/graphql/query', (req, res) => {
  const q = (req.query.query || '').toString();
  if (!q) return res.status(400).json({ errors: [{ message: 'query param required' }] });
  pccExecuteGraphQL({ query: q })
    .then(r => res.json(r))
    .catch(e => res.status(400).json({ errors: [{ message: String(e && e.message || e) }] }));
});

