pccCatalog.get('/modules', (req, res) => {
  res.json(PCC_CATALOG_DATA);
});

pccCatalog.get('/categories', (req, res) => {
  const out = {};
  for (const cat of PCC_CATALOG_DATA.categories) {
    out[cat] = PCC_CATALOG_DATA.modules.filter(m => m.startsWith('pcc-' + cat + '-') || m === 'pcc-' + cat || m.startsWith('pcc-' + cat));
  }
  res.json({ version: PCC_CATALOG_DATA.version, count: PCC_CATALOG_DATA.categories.length, categories: out });
});

// v3.316.11 — Rich catalog stats (extended fields: top_categories, duplicate_function_names, version stamp)
// v3.316.31 — fix hardcoded counts to match actual coverage (was: categories: 255 stale)
//   Now computes categories dynamically via the same logic as /coverage (single source of truth).
pccCatalog.get('/stats', (req, res) => {
  const modules = PCC_MODULES_LOOKUP;
  const totalFunctions = modules.reduce((s, m) => s + m.function_count, 0);
  const avg = (totalFunctions / modules.length).toFixed(2);
  // Recompute categories dynamically (matches /coverage logic post-3.316.31)
  const catCounts = {};
  for (const m of modules) {
    const parts = (m.url_slug || '').split('-').slice(1);
    const key = parts[0] || 'misc';
    catCounts[key] = (catCounts[key] || 0) + 1;
  }
  const topCats = Object.entries(catCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, count]) => ({ name, count }));
  res.json({
    version: '3.316.230',
    modules: modules.length,
    categories: Object.keys(catCounts).length,
    total_functions: totalFunctions,
    avg_functions_per_module: parseFloat(avg),
    duplicate_function_names: 703,
    top_categories: topCats,
    ts: new Date().toISOString()
  });
});

// v3.316.12: per-category module coverage breakdown
// v3.316.31: fix bug — single-word categories (e.g. 'pcc-ambulatory') were misclassified as 'misc'
//   because parts.length === 1 (only the category name, no trailing -ext etc.). Now we use
//   parts[0] when it's the only element. Also align total_categories with actual module count.
pccCatalog.get('/coverage', (req, res) => {
  const cat = {};
  for (const m of PCC_MODULES_LOOKUP) {
    // Derive a category from the slug prefix (pcc-<category>[-suffix...])
    const parts = (m.url_slug || '').split('-').slice(1);
    let key;
    if (parts.length >= 2) key = parts[0];            // pcc-cardio-ext → 'cardio'
    else if (parts.length === 1) key = parts[0];      // pcc-ambulatory → 'ambulatory' (was 'misc')
    else key = 'misc';
    if (!cat[key]) cat[key] = { category: key, modules: 0, total_functions: 0 };
    cat[key].modules++;
    cat[key].total_functions += (m.function_count || 0);
  }
  const out = Object.values(cat).map(c => ({
    category: c.category,
    modules: c.modules,
    total_functions: c.total_functions,
    avg_functions: +(c.total_functions / c.modules).toFixed(2)
  })).sort((a, b) => b.modules - a.modules);
  res.json({
    version: '3.316.230',
    total_categories: out.length,
    breakdown: out,
    ts: new Date().toISOString()
  });
});

// v3.316.12: random module picker (useful for explore/demo)
function pccRng(seed) {
  let t = (seed | 0) || Date.now();
  return () => {
    t = (t + 0x6D2B79F5) | 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}
pccCatalog.get('/random', (req, res) => {
  const seed = req.query.seed ? parseInt(req.query.seed, 10) : Date.now();
  const rng = pccRng(seed);
  const idx = Math.floor(rng() * PCC_MODULES_LOOKUP.length);
  const m = PCC_MODULES_LOOKUP[idx];
  res.json({
    version: '3.316.230',
    seed,
    index: idx,
    module: m
  });
});

// v3.316.13: cross-module function duplicates
pccCatalog.get('/duplicates', (req, res) => {
  const counts = new Map();
  for (const m of PCC_MODULES_LOOKUP) {
    const seen = new Set();
    for (const fn of (m.functions || [])) {
      if (seen.has(fn)) continue;
      seen.add(fn);
      if (!counts.has(fn)) counts.set(fn, []);
      counts.get(fn).push(m.url_slug);
    }
  }
  const dups = [];
  for (const [fn, modules] of counts.entries()) {
    if (modules.length > 1) dups.push({ function: fn, modules, count: modules.length });
  }
  dups.sort((a, b) => b.count - a.count);
  res.json({
    version: '3.316.230',
    total_duplicate_names: dups.length,
    top_collisions: dups.slice(0, 20),
    sample: dups.slice(0, 50),
    ts: new Date().toISOString()
  });
});

