// v3.316.26: snapshot listing endpoint
app.get('/api/v1/pcc-catalog/snapshots', (_req, res) => {
  const fs = require('fs');
  const idxPath = path.join(__dirname, 'public', 'snapshots', 'index.json');
  try {
    if (!fs.existsSync(idxPath)) {
      return res.json({ count: 0, snapshots: [] });
    }
    const data = JSON.parse(fs.readFileSync(idxPath, 'utf8'));
    res.json({ count: Array.isArray(data) ? data.length : 0, snapshots: data });
  } catch (e) {
    res.status(500).json({ error: 'snapshots_read_failed', message: e.message });
  }
});

// v3.316.29: Compare two snapshots and report deltas
// Query params:
//   from=YYYY-MM-DD.json  (default: 2nd-most-recent)
//   to=YYYY-MM-DD.json    (default: most-recent)
app.get('/api/v1/pcc-catalog/snapshots/diff', (req, res) => {
  const fs = require('fs');
  const path = require('path');
  const dir = path.join(__dirname, 'public', 'snapshots');
  try {
    const indexPath = path.join(dir, 'index.json');
    if (!fs.existsSync(indexPath)) {
      return res.status(404).json({ error: 'no_snapshots_found' });
    }
    const index = JSON.parse(fs.readFileSync(indexPath, 'utf8'));
    if (!Array.isArray(index) || index.length < 1) {
      return res.status(404).json({ error: 'no_snapshots_found' });
    }
    // Pick files: explicit ?from/?to or default to most recent two
    const fromName = req.query.from || (index[1] && index[1].filename);
    const toName = req.query.to || index[0].filename;
    if (!fromName || !toName) {
      return res.status(400).json({ error: 'need_at_least_2_snapshots', available: index.length });
    }
    const fromPath = path.join(dir, fromName);
    const toPath = path.join(dir, toName);
    if (!fs.existsSync(fromPath) || !fs.existsSync(toPath)) {
      return res.status(404).json({ error: 'snapshot_file_missing', from: fromName, to: toName });
    }
    const from = JSON.parse(fs.readFileSync(fromPath, 'utf8'));
    const to = JSON.parse(fs.readFileSync(toPath, 'utf8'));
    const delta = {
      from: fromName,
      to: toName,
      captured_from: from.captured_at,
      captured_to: to.captured_at,
      uptime_delta_seconds: (to.uptime_seconds || 0) - (from.uptime_seconds || 0),
      memory_delta_mb: (to.memory_mb || 0) - (from.memory_mb || 0),
      tokens_delta: (to.tokens_count || 0) - (from.tokens_count || 0),
      audit_delta: (to.audit_count || 0) - (from.audit_count || 0),
      build_changed: from.build !== to.build,
    };
    res.json(delta);
  } catch (e) {
    res.status(500).json({ error: 'diff_failed', message: e.message });
  }
});

