// v3.316.24: Dynamic SVG badge with module count (shields.io-style, two segments).
// Placed right after PCC_MODULES_LOOKUP so the closure can read module/function counts.
app.get('/api/v1/pcc-catalog/badge.svg', (_req, res) => {
  const lookup = PCC_MODULES_LOOKUP;
  const moduleCount = Array.isArray(lookup) ? lookup.length : Object.keys(lookup || {}).length;
  const functionCount = Array.isArray(lookup)
    ? lookup.reduce((s, m) => s + (m.function_count || 0), 0)
    : 0;
  // shields.io-style badge with two segments
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="180" height="20" role="img" aria-label="PCC Sandbox: ${moduleCount} modules">
  <title>PCC Sandbox: ${moduleCount} modules, ${functionCount} functions</title>
  <linearGradient id="g" x2="0" y2="100%">
    <stop offset="0" stop-color="#bbb" stop-opacity=".1"/>
    <stop offset="1" stop-opacity=".1"/>
  </linearGradient>
  <clipPath id="r"><rect width="180" height="20" rx="3" fill="#fff"/></clipPath>
  <g clip-path="url(#r)">
    <rect width="80" height="20" fill="#555"/>
    <rect x="80" width="100" height="20" fill="#10b981"/>
    <rect width="180" height="20" fill="url(#g)"/>
  </g>
  <g fill="#fff" text-anchor="middle" font-family="Verdana,Geneva,DejaVu Sans,sans-serif" font-size="11">
    <text x="40" y="14">PCC Sandbox</text>
    <text x="130" y="14">${moduleCount} modules</text>
  </g>
</svg>`;
  res.type('image/svg+xml; charset=utf-8').send(svg);
});

// Tokenize query (same as generator)
function pccTokenize(text) {
  const STOPWORDS = new Set(['pcc', 'ext', 'med', 'module']);
  return String(text).toLowerCase()
    .replace(/[_-]/g, ' ')
    .split(/\s+/)
    .filter(t => t.length >= 2 && !STOPWORDS.has(t));
}

pccSearchRouter.get('/search', (req, res) => {
  const q = (req.query.q || '').toString().trim();
  if (!q) return res.status(400).json({ error: 'q query param required' });
  const tokens = pccTokenize(q);
  if (tokens.length === 0) return res.json({ query: q, count: 0, results: [] });

  // Score: count of matched tokens per module
  const scores = {};
  for (const t of tokens) {
    const matches = PCC_SEARCH_INDEX[t] || [];
    for (const slug of matches) {
      scores[slug] = (scores[slug] || 0) + 1;
    }
  }

  const results = Object.entries(scores)
    .map(([slug, score]) => ({
      slug,
      score,
      module: PCC_MODULES_LOOKUP.find(m => m.url_slug === slug)
    }))
    .filter(r => r.module)
    .sort((a, b) => b.score - a.score)
    .slice(0, 50);

  res.json({
    query: q,
    tokens,
    count: results.length,
    results: results.map(r => ({
      slug: r.slug,
      score: r.score,
      module: r.module.module,
      version: r.module.version,
      function_count: r.module.function_count
    }))
  });
});

pccSearchRouter.get('/lookup/:fn', (req, res) => {
  const fn = req.params.fn;
  const slugs = PCC_FUNC_INDEX[fn] || [];
  if (slugs.length === 0) return res.status(404).json({ error: 'function not found', fn });
  const modules = slugs.map(slug => {
    const m = PCC_MODULES_LOOKUP.find(mod => mod.url_slug === slug);
    return m ? { slug, module: m.module, version: m.version } : null;
  }).filter(Boolean);
  res.json({ fn, count: modules.length, modules });
});

pccSearchRouter.get('/stats', (req, res) => {
  res.json({
    version: '3.316.230',
    total_modules: PCC_MODULES_LOOKUP.length,
    unique_tokens: Object.keys(PCC_SEARCH_INDEX).length,
    indexed_functions: Object.keys(PCC_FUNC_INDEX).length,
    total_functions: PCC_MODULES_LOOKUP.reduce((s, m) => s + m.function_count, 0),
    avg_functions_per_module: +(PCC_MODULES_LOOKUP.reduce((s, m) => s + m.function_count, 0) / PCC_MODULES_LOOKUP.length).toFixed(2)
  });
});

app.use('/api/v1/pcc-catalog', pccSearchRouter);
app.use('/api/v1/pcc-catalog', pccCatalog);


