// v3.316.18: load benchmark endpoint — runs N concurrent requests against a target
// read endpoint and returns latency / throughput stats. Used for capacity planning.
pccDiagRouter.get('/bench/run', async (req, res) => {
  const count = Math.min(parseInt(req.query.count || '100', 10) || 100, 500);
  const target = req.query.target || '/api/v1/pcc-catalog/modules';
  const concurrent = Math.min(parseInt(req.query.concurrent || '10', 10) || 10, 50);

  const start = Date.now();
  const latencies = [];
  let errors = 0;

  const http = require('http');
  const url = new URL(target, `http://127.0.0.1:${process.env.PCC_PORT || 3100}`);

  const fetchOnce = () => new Promise(resolve => {
    const t0 = Date.now();
    const req2 = http.get(url.toString(), { headers: { 'User-Agent': 'pcc-bench' } }, r => {
      // Drain response
      const chunks = [];
      r.on('data', c => chunks.push(c));
      r.on('end', () => {
        latencies.push(Date.now() - t0);
        resolve(r.statusCode);
      });
    });
    req2.on('error', () => { errors++; resolve(0); });
    req2.setTimeout(10000, () => { req2.destroy(); errors++; resolve(0); });
  });

  // Run in batches of `concurrent`
  const batches = Math.ceil(count / concurrent);
  for (let b = 0; b < batches; b++) {
    const batchSize = Math.min(concurrent, count - b * concurrent);
    const promises = [];
    for (let i = 0; i < batchSize; i++) promises.push(fetchOnce());
    await Promise.all(promises);
  }

  const elapsed = Date.now() - start;
  const sorted = latencies.slice().sort((a, b) => a - b);
  const sum = latencies.reduce((s, x) => s + x, 0);
  const stats = {
    version: '3.316.230',
    target,
    total_requests: count,
    completed: latencies.length,
    errors,
    elapsed_ms: elapsed,
    requests_per_second: latencies.length > 0 ? Math.round((latencies.length / elapsed) * 1000) : 0,
    latency_ms: {
      min: sorted[0] || 0,
      max: sorted[sorted.length - 1] || 0,
      avg: latencies.length > 0 ? Math.round(sum / latencies.length) : 0,
      p50: sorted[Math.floor(sorted.length * 0.5)] || 0,
      p95: sorted[Math.floor(sorted.length * 0.95)] || 0,
      p99: sorted[Math.floor(sorted.length * 0.99)] || 0
    },
    concurrent,
    ts: new Date().toISOString()
  };
  res.json(stats);
});

app.use('/api/v1/pcc-diagnostics', pccDiagRouter);




// --- Error handler ---
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  const statusCode = err.statusCode || 500;
  if (statusCode >= 500) {
    // eslint-disable-next-line no-console
    console.error('PCC error:', err);
  }
  res.status(statusCode).json({
    error: err.message,
    code: err.code,
  });
});

