// v3.316.23: register metrics gauge callbacks. Derived live from the
// in-memory PCC_MODULES_LOOKUP catalog so the numbers stay in sync with the
// actual module set. PCC_MODULES_LOOKUP is a module-local `const`; we close
// over the binding here so the getter always sees the current value.
const pccModuleCountFn = () => {
  return Array.isArray(PCC_MODULES_LOOKUP) ? PCC_MODULES_LOOKUP.length : 0;
};
const pccFunctionCountFn = () => {
  if (!Array.isArray(PCC_MODULES_LOOKUP)) return 0;
  let total = 0;
  for (const m of PCC_MODULES_LOOKUP) {
    if (!m) continue;
    if (Array.isArray(m.functions)) {
      total += m.functions.length;
    } else if (typeof m.function_count === 'number') {
      total += m.function_count;
    } else if (Array.isArray(m.fns)) {
      total += m.fns.length;
    }
  }
  return total;
};
initMetrics({
  getModuleCount: pccModuleCountFn,
  getFunctionCount: pccFunctionCountFn,
});
