function shutdown(sig) {
  // eslint-disable-next-line no-console
  console.log(`PCC ${sig} received, shutting down`);
  server.close(async () => {
    // v3.316.21: drain audit buffer (must run before closeDb)
    try { closeAuditStore(); } catch (_) { /* ignore */ }
    // v3.316.25: close token store (clear cached pool ref)
    try { closeTokenStore(); } catch (_) { /* ignore */ }
    try { await closeDb(); } catch (_) { /* ignore */ }
    process.exit(0);
  });
  setTimeout(() => process.exit(1), 5000).unref();
}
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

module.exports = app;














